window.PIATTAFORMA_SEED_COMPITI = window.PIATTAFORMA_SEED_COMPITI.concat([{"class_id": "5g", "title": "La mia mappa del cyberspace", "description": "Scegli 3 servizi che usi ogni giorno e seguili strato per strato: risolvi il dominio, esegui tracert, scopri con RDAP a chi è assegnato l'IP e compila per ognuno la tabella dei tre livelli. Chiudi con una riflessione su paesi e leggi coinvolti e consegna il file mappa-cyberspace-cognome.pdf.", "due_date": null, "planned_due": "2026-10-30", "topic": "Il cyberspace", "pdf_url": "contenuti/compiti/cyberspace.pdf", "group_work": false}, {"class_id": "5g", "title": "Consulente per un giorno", "description": "Per un'azienda inventata ma realistica elenca almeno 8 asset con i valori CIA, compila un registro di almeno 10 rischi con R = P × I, livello e trattamento, e prepara un piano con RTO, RPO, contromisure per funzione NIST CSF 2.0 e una valutazione NIS2. Consegna il file consulente-cognome.ods con i fogli Asset, Rischi e Piano.", "due_date": null, "planned_due": "2026-11-04", "topic": "Le basi della cybersecurity aziendale", "pdf_url": "contenuti/compiti/cybersecurity-aziendale.pdf", "group_work": false}, {"class_id": "5g", "title": "Anatomia di un attacco vero", "description": "Scegli un attacco documentato (per esempio WannaCry, NotPetya o Colonial Pipeline) e, con almeno 3 fonti affidabili, descrivi il profilo dell'attaccante, le 7 fasi della kill chain, almeno 5 tecniche MITRE ATT&CK, l'impatto e le due contromisure che l'avrebbero fermato prima. Consegna il file attacco-cognome.pdf.", "due_date": null, "planned_due": "2026-11-09", "topic": "Attaccanti: i Cybercriminali", "pdf_url": "contenuti/compiti/cybercriminali.pdf", "group_work": false}, {"class_id": "5g", "title": "Il mio SIEM fa un passo avanti", "description": "Estendi il MiniSiem.java della lezione con la regola del viaggio impossibile (stesso utente, accessi riusciti da paesi diversi a meno di 60 minuti), mantenendo quella del brute force, e prova tutto con un log di almeno 12 righe. Nel README indica output atteso, tecniche ATT&CK e falsi positivi possibili; consegna il file siem-cognome.zip.", "due_date": null, "planned_due": "2026-11-12", "topic": "Difensori: gli esperti di Cybersecurity (cyberdefender)", "pdf_url": "contenuti/compiti/cyberdefender.pdf", "group_work": false}, {"class_id": "5g", "title": "Tre falle nel negozio", "description": "Avvia OWASP Juice Shop sul tuo computer e risolvi 3 nuove sfide da 1 o 2 stelle. Per ognuna indica la categoria OWASP Top 10, i passi fatti con una schermata, la causa dell'errore e la correzione con un frammento di codice o di configurazione. Consegna il file juice-shop-cognome.pdf.", "due_date": null, "planned_due": "2026-11-18", "topic": "Network e Web App Security", "pdf_url": "contenuti/compiti/network-web-security.pdf", "group_work": false}, {"class_id": "5g", "title": "La mia prima write-up", "description": "Supera almeno 4 nuovi livelli di OverTheWire Bandit e una sfida di picoGym di una categoria diversa da General Skills, e documenta ognuno con obiettivo, idea, comandi e che cosa hai imparato, senza scrivere le password. Chiudi con quale categoria vorresti approfondire e consegna il file writeup-cognome.md.", "due_date": null, "planned_due": "2026-11-23", "topic": "Cyberchallenge: Capture the Flag", "pdf_url": "contenuti/compiti/capture-the-flag.pdf", "group_work": false}, {"class_id": "5g", "title": "Autopsia di un disservizio", "description": "Scegli il resoconto ufficiale (post-mortem) di un disservizio reale di un grande servizio online e analizzalo: cronologia, causa radice, propagazione del guasto, fallacie del calcolo distribuito dimostrate, scelta tra coerenza e disponibilità e contromisure. Consegna il file autopsia-cognome.pdf.", "due_date": null, "planned_due": "2026-11-26", "topic": "I sistemi distribuiti", "pdf_url": "contenuti/compiti/sistemi-distribuiti.pdf", "group_work": false}, {"class_id": "5g", "title": "Il registro remoto con Java RMI", "description": "Scrivi un servizio Java RMI che conserva i voti degli studenti con le operazioni aggiungiVoto e media, con controllo dei valori non validi, e un client che lo usa. Rispondi poi a tre domande su ritrasmissioni, idempotenza e RemoteException. Consegna il file registro-rmi-cognome.zip con i sorgenti e risposte.txt.", "due_date": null, "planned_due": "2026-12-01", "topic": "La comunicazione con RPC", "pdf_url": "contenuti/compiti/comunicazione-rpc.pdf", "group_work": false}, {"class_id": "5g", "title": "Il cinema multisala a servizi", "description": "Progetta l'architettura a servizi per la vendita di biglietti di una catena di cinema: servizi e dati, tabella delle rotte dell'API gateway, flusso di acquisto, gestione dei guasti e del posto conteso, giustificazione della scelta tra microservizi e monolite. Consegna il file cinema-architettura-cognome.pdf.", "due_date": null, "planned_due": "2026-12-04", "topic": "Le architetture orientate ai servizi", "pdf_url": "contenuti/compiti/architetture-soa.pdf", "group_work": false}, {"class_id": "5g", "title": "Il cambio del giorno: da XML a JSON", "description": "Scrivi un programma Java che legge con il parser XML del JDK i cambi dell'euro pubblicati dalla Banca Centrale Europea e produce un file JSON valido con data e quattro valute, gestendo l'errore di rete. Consegna il file cambi-cognome.zip con Cambi.java, cambi.json e risposte.txt.", "due_date": null, "planned_due": "2026-12-10", "topic": "I web service", "pdf_url": "contenuti/compiti/web-service.pdf", "group_work": false}, {"class_id": "5g", "title": "Detective HTTP", "description": "Cattura con curl o DevTools sei scambi HTTP reali con codici diversi (200, 3xx, 304, 404, 401 o 403, 405), spiega riga per riga uno scambio, scrivi a mano una richiesta POST con il Content-Length esatto e chiarisci la differenza tra metodi sicuri e idempotenti. Consegna il file detective-http-cognome.pdf.", "due_date": null, "planned_due": "2026-12-15", "topic": "I web service e il protocollo HTTP", "pdf_url": "contenuti/compiti/protocollo-http.pdf", "group_work": false}, {"class_id": "5g", "title": "Partite IVA d'Europa: un servizio SOAP vero", "description": "Analizza il WSDL pubblico del servizio europeo VIES, scrivi a mano la busta SOAP per l'operazione checkVat e inviala con curl, prova i casi d'errore e disegna lo schema del WSDL. Consegna il file vies-cognome.zip con checkvat.xml, risposta.xml e analisi.pdf.", "due_date": null, "planned_due": "2026-12-21", "topic": "I web service con SOAP", "pdf_url": "contenuti/compiti/soap-wsdl.pdf", "group_work": false}, {"class_id": "5g", "title": "Il servizio Pagella", "description": "Crea con Maven un servizio SOAP che trasforma un voto in giudizio e calcola la media di una lista di voti, con validazione dello schema e Fault per i valori non validi, prova cinque buste con curl e scrivi un client generato con wsimport. Consegna il file pagella-soap-cognome.zip con i due progetti senza target, le buste e prove.txt.", "due_date": null, "planned_due": "2027-01-08", "topic": "Web service SOAP in Java", "pdf_url": "contenuti/compiti/soap-java.pdf", "group_work": false}, {"class_id": "5g", "title": "L'API delle prenotazioni dei laboratori", "description": "Progetta l'API REST con cui i docenti prenotano i laboratori della scuola: risorse e URI, una tabella di almeno 10 endpoint con metodi e codici di stato, esempi JSON e tre scelte motivate (prenotazione doppia, PUT o PATCH, filtri), più l'analisi della documentazione di Open-Meteo. Consegna il file api-prenotazioni-cognome.pdf.", "due_date": null, "planned_due": "2027-01-13", "topic": "I web service con REST", "pdf_url": "contenuti/compiti/rest-web-service.pdf", "group_work": false}, {"class_id": "5g", "title": "BiblioAPI: arrivano i prestiti", "description": "Estendi il BiblioServer scritto in classe con la risorsa prestiti: prestito di un libro con 201, 404 e 409 se è già prestato, elenco con il filtro attivi=true, restituzione con PUT e filtro dei libri per autore. Consegna il file biblioapi-prestiti-cognome.zip con BiblioServer.java e prove.txt con l'output di curl.", "due_date": null, "planned_due": "2027-01-18", "topic": "Sviluppo di un web service RESTful in Java", "pdf_url": "contenuti/compiti/rest-java.pdf", "group_work": false}, {"class_id": "5g", "title": "BiblioCLI: la biblioteca dal terminale", "description": "Scrivi un client Java a menu che usa BiblioAPI per elencare, cercare, aggiungere, modificare ed eliminare libri, gestendo 404, 400, input non valido e server spento senza mai crollare; bonus una pagina cerca.jsp. Consegna il file bibliocli-cognome.zip con BiblioCLI.java e sessione.txt.", "due_date": null, "planned_due": "2027-01-21", "topic": "Utilizzo di web service REST in Java e JSP", "pdf_url": "contenuti/compiti/rest-client-jsp.pdf", "group_work": false}, {"class_id": "5g", "title": "Collaudatore di API per un giorno", "description": "Porta la collezione di test di BiblioAPI ad almeno 12 richieste con variabili e test automatici, di cui almeno 6 casi negativi, eseguila con il Runner e scrivi un rapporto con la tabella dei casi di test e i difetti trovati. Consegna il file collaudo-cognome.zip con la collezione esportata e collaudo-cognome.pdf.", "due_date": null, "planned_due": "2027-01-26", "topic": "Test di web service REST con Curl e Postman", "pdf_url": "contenuti/compiti/rest-curl-postman.pdf", "group_work": false}, {"class_id": "5g", "title": "Il meteo della gita", "description": "Costruisci una pagina web che chiama in parallelo l'API di Open-Meteo per tre mete, mostra in una tabella temperatura massima e probabilità di pioggia dei prossimi giorni e indica la meta e il giorno migliori per la gita, gestendo gli errori. Consegna il file meteo-gita-cognome.zip con meteo-gita.html e uno screenshot.", "due_date": null, "planned_due": "2027-01-29", "topic": "Utilizzo di web service REST in JavaScript", "pdf_url": "contenuti/compiti/rest-javascript.pdf", "group_work": false}, {"class_id": "5g", "title": "Il diario della latenza", "description": "Completa PingSistema.java, che lancia il ping del sistema con ProcessBuilder, calcola minimo, media, massimo, jitter e perdita e aggiunge una riga a un CSV; misura tre destinazioni in momenti diversi e spiega i risultati in una relazione di una pagina. Consegna il file latenza-cognome.zip con PingSistema.java, Statistiche.java, latenza.csv e relazione.pdf.", "due_date": null, "planned_due": "2027-02-04", "topic": "L'efficienza della comunicazione: il ping", "pdf_url": "contenuti/compiti/ping-java.pdf", "group_work": false}, {"class_id": "5g", "title": "Il cruscotto della rete", "description": "Scrivi Cruscotto.java, che controlla in parallelo una lista di host e servizi (ICMP e TCP) con tre strategie (sequenziale, pool fisso, virtual thread), ne misura i tempi e genera una pagina HTML di stato; commenta i tempi ottenuti. Consegna il file cruscotto-cognome.zip con Cruscotto.java, controlli.txt, cruscotto.html e tempi.txt.", "due_date": null, "planned_due": "2027-02-09", "topic": "Il controllo della rete: il ping multiplo", "pdf_url": "contenuti/compiti/ping-multiplo.pdf", "group_work": false}, {"class_id": "5g", "title": "Chat 2.0: nuovi comandi", "description": "Estendi la chat del laboratorio con nickname unici, il comando LIST e i messaggi privati PRIV, usa i virtual thread e documenta il protocollo; anche in gruppo fino a 3 persone. Consegna il file chat-cognome.zip con i tre file Java, protocollo.md e prova.pdf con gli screenshot di tre client.", "due_date": null, "planned_due": "2027-02-12", "topic": "La comunicazione socket: la chat", "pdf_url": "contenuti/compiti/chat-socket.pdf", "group_work": true}, {"class_id": "5g", "title": "Il sondaggio in diretta", "description": "Realizza un sondaggio in tempo reale: il browser invia i voti via WebSocket e il server (Tomcat o il server alternativo solo JDK allegato) manda a tutti i conteggi in JSON, aggiornando le barre su ogni schermo; anche in gruppo fino a 3 persone. Consegna il file sondaggio-cognome.zip con il server, index.html e prova.pdf.", "due_date": null, "planned_due": "2027-02-17", "topic": "La comunicazione WebSocket tra browser e server", "pdf_url": "contenuti/compiti/websocket-chat.pdf", "group_work": true}, {"class_id": "5g", "title": "La pagella mobile di un'app", "description": "Scegli un'app che usi ogni giorno e misurane consumo di batteria (in Wh), dati, permessi e comportamento con una rete lenta, poi indica se è nativa, web, ibrida o multipiattaforma e proponi tre miglioramenti legati ai vincoli dei dispositivi mobili. Consegna il file pagella-app-cognome.pdf.", "due_date": null, "planned_due": "2027-02-22", "topic": "Caratteristiche e problematiche", "pdf_url": "contenuti/compiti/mobile-caratteristiche.pdf", "group_work": false}, {"class_id": "5g", "title": "Il mio telefono ai raggi X", "description": "Fai il controllo di sicurezza del tuo telefono: versione di Android e patch, audit dei permessi di sei app con la revoca di quelli inutili, poi prevedi i callback del ciclo di vita in tre scenari e spiega il problema della rotazione. Consegna il file raggi-x-cognome.pdf.", "due_date": null, "planned_due": "2027-02-25", "topic": "Il sistema operativo Android", "pdf_url": "contenuti/compiti/android-sistema.pdf", "group_work": false}, {"class_id": "5g", "title": "Traduci la pagella in Kotlin", "description": "Riscrivi in Kotlin idiomatico un programma Java che stampa una pagella con un voto mancante, usando data class, tipo nullable senza !!, when e lambda, e ottieni lo stesso output. Consegna il file traduzione-cognome.kt con l'output in un commento finale.", "due_date": null, "planned_due": "2027-03-03", "topic": "Conoscere Kotlin per sviluppare App Android", "pdf_url": "contenuti/compiti/kotlin-base.pdf", "group_work": false}, {"class_id": "5g", "title": "QuizTPSI ha un'identità", "description": "Personalizza nome e icona della tua app, poi provoca sei situazioni (rotazione, Home, notifiche, blocco schermo, Indietro…) scrivendo prima la previsione e poi i callback che compaiono davvero in Logcat, con tre screenshot e tre brevi risposte. Consegna il file prima-app-cognome.pdf.", "due_date": null, "planned_due": "2027-03-08", "topic": "La prima App in Android Studio", "pdf_url": "contenuti/compiti/android-prima-app.pdf", "group_work": false}, {"class_id": "5g", "title": "Una schermata per tutti", "description": "Completa la schermata della domanda con tre domande e immagini, sposta tutti i testi nelle risorse e crea la traduzione inglese, poi verifica il layout con i caratteri al massimo e correggi ciò che si taglia. Consegna il file layout-cognome.zip con layout, stringhe, note.txt e tre screenshot.", "due_date": null, "planned_due": "2027-03-11", "topic": "La modifica del layout: TextView e ImageView", "pdf_url": "contenuti/compiti/android-layout.pdf", "group_work": false}, {"class_id": "5g", "title": "Un quiz a prova di utente", "description": "Porta QuizTPSI a cinque domande, aggiungi un pulsante Aiuto con suggerimento in un Toast e una penalità sul punteggio, impedisci le risposte doppie e salva tutto lo stato alla rotazione, documentando almeno sei test. Consegna il file quiz-cognome.zip con app/src/main e test.txt.", "due_date": null, "planned_due": "2027-03-16", "topic": "L'interattività: Button e Toast", "pdf_url": "contenuti/compiti/android-button-toast.pdf", "group_work": false}, {"class_id": "5g", "title": "QuizTPSI 1.0", "description": "Completa l'app con la schermata del risultato e un messaggio scelto con when, Gioca ancora con finish(), condivisione e una InfoActivity che apre una pagina web, poi disegna il diagramma di navigazione con Intent, dati e back stack. Consegna il file quiztpsi-cognome.zip con app/src/main e navigazione.pdf.", "due_date": null, "planned_due": "2027-03-19", "topic": "Una nuova pagina: Intent e New Activity", "pdf_url": "contenuti/compiti/android-intent.pdf", "group_work": false}, {"class_id": "5g", "title": "Il brief del nostro cliente (lavoro di gruppo)", "description": "La squadra sceglie un cliente vero (associazione del territorio o club della scuola), lo intervista e scrive il brief con obiettivi SMART, due personas, sei user story, almeno dieci requisiti F/NF con priorità MoSCoW, la scelta tecnologica motivata e il calendario. Il referente consegna il file u5-brief-squadraN.pdf.", "due_date": null, "planned_due": "2027-03-24", "topic": "Il progetto di un sito", "pdf_url": "contenuti/compiti/progetto-sito.pdf", "group_work": true}, {"class_id": "5g", "title": "Mappa del sito e wireframe (lavoro di gruppo)", "description": "La squadra completa l'inventario dei contenuti, fa un card sorting con tre persone esterne, disegna la mappa del sito e i wireframe mobile e desktop di tre pagine, e li prova con due persone. Il referente consegna il file u5-mappa-wireframe-squadraN.pdf.", "due_date": null, "planned_due": "2027-04-02", "topic": "Progetto generale del sito", "pdf_url": "contenuti/compiti/mappa-sito.pdf", "group_work": true}, {"class_id": "5g", "title": "La home responsive (lavoro di gruppo)", "description": "La squadra realizza la home del sito in HTML semantico e CSS mobile first, con guida di stile in variabili CSS e contrasti verificati, immagini ottimizzate e misure Lighthouse prima e dopo. Il referente consegna il file u5-responsive-squadraN.zip con codice, screenshot a tre larghezze e lighthouse.md.", "due_date": null, "planned_due": "2027-04-08", "topic": "Problematiche di Web Design", "pdf_url": "contenuti/compiti/web-design.pdf", "group_work": true}, {"class_id": "5g", "title": "Farsi trovare (lavoro di gruppo)", "description": "La squadra individua le ricerche reali degli utenti, scrive title e description per ogni pagina, prepara sitemap.xml, robots.txt e dati strutturati JSON-LD validati, porta Lighthouse SEO a 100 e riflette su come il sito potrebbe essere citato dalle risposte AI. Il referente consegna il file u5-seo-squadraN.zip.", "due_date": null, "planned_due": "2027-04-13", "topic": "SEO, Search Engine Optimization", "pdf_url": "contenuti/compiti/seo-motori-ricerca.pdf", "group_work": true}, {"class_id": "5g", "title": "L'audit di accessibilità (lavoro di gruppo)", "description": "La squadra fa l'audit di tre pagine del proprio sito con WAVE, Lighthouse, tastiera, screen reader, zoom e contrasti, riporta almeno otto problemi con il criterio WCAG, li corregge e rimisura, confronta gli alt generati dall'AI con i propri e scrive una breve dichiarazione di accessibilità. Il referente consegna il file u5-audit-squadraN.pdf.", "due_date": null, "planned_due": "2027-04-16", "topic": "Accessibilità e supporto ai disabili", "pdf_url": "contenuti/compiti/accessibilita-web.pdf", "group_work": true}, {"class_id": "5g", "title": "Online! Test, pubblicazione e consegna (lavoro di gruppo)", "description": "La squadra esegue un piano di almeno 15 test, valida le pagine, pubblica il sito su un hosting statico con HTTPS, documenta nslookup, curl e Lighthouse e scrive il piano di manutenzione per il cliente; ogni studente aggiunge una riflessione individuale. Il referente consegna il file u5-pubblicazione-squadraN.pdf con l'indirizzo del sito.", "due_date": null, "planned_due": "2027-04-21", "topic": "Test, pubblicazione e aggiornamento", "pdf_url": "contenuti/compiti/pubblicare-sito.pdf", "group_work": true}, {"class_id": "5g", "title": "Il consulente sei tu", "description": "Intervista una piccola realtà che conosci e risali dal problema al vero bisogno con la tecnica dei 5 perché. In Calc scrivi almeno 12 requisiti classificati (F/NF, MoSCoW) con il criterio di accettazione, i vincoli e la risposta make or buy. Consegna il file requisiti-cognome.ods.", "due_date": null, "planned_due": "2027-04-26", "topic": "Processo di selezione", "pdf_url": "contenuti/compiti/processo-selezione.pdf", "group_work": false}, {"class_id": "5g", "title": "Indagine di mercato", "description": "Per il tuo cliente costruisci una long list di almeno 6 candidati con fonti e date, filtrala con i requisiti Must, valuta 4 fonti con il test CRAAP e scrivi una RFI di 8 domande. Consegna il file ricerca-cognome.ods con i fogli LongList, Fonti e RFI.", "due_date": null, "planned_due": "2027-04-29", "topic": "Processo di ricerca", "pdf_url": "contenuti/compiti/ricerca-prodotti.pdf", "group_work": false}, {"class_id": "5g", "title": "Il vero prezzo", "description": "Scegli una categoria di software per uno studio di 10 persone e confronta 3 opzioni reali con licenze diverse: calcola in Calc il TCO su 3 anni con parametri, classifica le licenze e ricava dalle pagine ufficiali SLA, localizzazione dei dati ed esportazione. Consegna il file tco-cognome.ods.", "due_date": null, "planned_due": "2027-05-04", "topic": "Valutazione dei prodotti e dei fornitori", "pdf_url": "contenuti/compiti/valutazione-fornitori.pdf", "group_work": false}, {"class_id": "5g", "title": "La scelta motivata", "description": "Costruisci per il tuo cliente la matrice pesata in Calc: filtro dei Must, pesi motivati, descrittori, punteggi con MATR.SOMMA.PRODOTTO e analisi di sensibilità con il punto di svolta. Scrivi la relazione di scelta e consegna il file scelta-cognome.pdf.", "due_date": null, "planned_due": "2027-05-10", "topic": "Valutazione comparata", "pdf_url": "contenuti/compiti/valutazione-comparata.pdf", "group_work": false}, {"class_id": "5g", "title": "Il mio primo accordo agile", "description": "Controlla una bozza di accordo di lavoro agile proposta da un'azienda inventata: per ogni clausola indica se è legittima, con l'articolo della legge 81/2017 o del DL 30/2021, riscrivi quelle non legittime e aggiungi due clausole che ti tutelerebbero. Consegna il file accordo-agile-cognome.pdf.", "due_date": null, "planned_due": "2027-05-13", "topic": "Lo smart working", "pdf_url": "contenuti/compiti/smart-working.pdf", "group_work": false}, {"class_id": "5g", "title": "Il mio lavoro nel 2035", "description": "Scegli la professione che vorresti fare, scomponila in 8 mansioni con la classificazione europea ESCO e valuta quali saranno automatizzate, potenziate dall'AI o resteranno umane, usando due fonti affidabili e classificando uno strumento di AI secondo l'AI Act. Consegna il file lavoro-2035-cognome.pdf.", "due_date": null, "planned_due": "2027-05-18", "topic": "La robotica e il mondo del lavoro", "pdf_url": "contenuti/compiti/robotica-lavoro.pdf", "group_work": false}, {"class_id": "5g", "title": "La guida PA per neodiplomati", "description": "Scrivi una guida per chi si diplomerà l'anno prossimo con sei situazioni reali (università, ISEE, primo stipendio, medico, residenza, concorsi): per ognuna servizio, sito ufficiale, credenziale, passi e una truffa da evitare. Completa poi il programma Java che verifica un codice fiscale. Consegna il file guida-pa-cognome.zip con il PDF e CodiceFiscale.java.", "due_date": null, "planned_due": "2027-05-21", "topic": "Il rapporto con la Pubblica Amministrazione", "pdf_url": "contenuti/compiti/pa-digitale.pdf", "group_work": false}, {"class_id": "5g", "title": "Progetto di gruppo: la casa domotica", "description": "In gruppo ripianificate il progetto della casa domotica del libro (obiettivi, ruoli, attività e tempi), sviluppate l'app di base e poi quella avanzata, e presentate i risultati alla classe. Consegnate un unico file casa-domotica-gruppo.zip con il codice sorgente, il piano del progetto in PDF e le slide della presentazione.", "due_date": null, "planned_due": "2027-03-19", "topic": "Learning by project: la casa domotica", "pdf_url": null, "group_work": true}, {"class_id": "5g", "title": "Progetto di gruppo: AB-Green e gli open data", "description": "In gruppo ripianificate il progetto AB-Green, cercate dataset sull'energia su dati.gov.it e data.europa.eu, integrateli nel sito usando le API CKAN e pubblicate il sito. Consegnate un unico file ab-green-gruppo.zip con il codice, un PDF che descrive i dataset usati e le chiamate API, e il link al sito pubblicato nella nota.", "due_date": null, "planned_due": "2027-05-14", "topic": "Learning by project: AB-Green", "pdf_url": null, "group_work": true}]);
window.PIATTAFORMA_SEED_VERIFICHE = (window.PIATTAFORMA_SEED_VERIFICHE || []).concat([{"class_id": "5g", "position": 10, "title": "Verifica Unità 1: cybersecurity", "description": "Triade CIA, rischio come probabilità per impatto e trattamenti, profili degli attaccanti, Cyber Kill Chain e tattiche MITRE ATT&CK, ruoli del SOC, lettura di un log con un attacco a forza bruta, risposta agli incidenti e scadenze NIS2, firewall, DMZ, VPN e segmentazione, OWASP Top 10, categorie ed etica delle CTF.", "test_date": "2026-11-27", "practice_url": "contenuti/verifiche/5g-u1-simulazione.pdf", "test_url": null, "solutions_url": null}, {"class_id": "5g", "position": 20, "title": "Verifica Unità 2: progettare e utilizzare web service", "description": "Sistemi distribuiti, RPC, architetture a servizi e microservizi, web service, XML e JSON, protocollo HTTP, SOAP e WSDL, SOAP in Java, REST, un servizio REST in Java, client Java e JSP, test con curl e Postman, fetch e CORS in JavaScript.", "test_date": "2027-02-02", "practice_url": "contenuti/verifiche/5g-u2-simulazione.pdf", "test_url": null, "solutions_url": null}, {"class_id": "5g", "position": 30, "title": "Verifica Unità 3: applicazioni Java per la comunicazione in rete", "description": "ICMP e ping, latenza, jitter e perdita, isReachable e ProcessBuilder, scansioni parallele con ExecutorService, Future e virtual thread, race condition, chat TCP multi-client e protocollo di testo, handshake e frame WebSocket, scelta motivata tra polling, SSE e WebSocket.", "test_date": "2027-02-22", "practice_url": "contenuti/verifiche/5g-u3-simulazione.pdf", "test_url": null, "solutions_url": null}, {"class_id": "5g", "position": 40, "title": "Verifica Unità 4: Applicazioni per sistemi mobili", "description": "Vincoli dei dispositivi mobili, architettura di Android, ciclo di vita, permessi, APK e AAB, Kotlin, layout, Button e Toast, Intent e Activity, con lettura e correzione di codice e il progetto di un'app.", "test_date": "2027-03-23", "practice_url": "contenuti/verifiche/5g-u4-simulazione.pdf", "test_url": null, "solutions_url": null}, {"class_id": "5g", "position": 50, "title": "Verifica Unità 5: realizzare un sito web", "description": "Brief, obiettivi SMART e requisiti, mappa del sito e wireframe, responsive design, contrasto e Core Web Vitals, SEO con robots.txt, noindex e dati strutturati, accessibilità WCAG 2.2 e normativa, test, DNS, codici HTTP e pubblicazione, con un progetto di sito da disegnare.", "test_date": "2027-04-26", "practice_url": "contenuti/verifiche/5g-u5-simulazione.pdf", "test_url": null, "solutions_url": null}, {"class_id": "5g", "position": 60, "title": "Verifica Unità 6: selezionare un prodotto informatico", "description": "Requisiti funzionali e non funzionali, MoSCoW, fonti e test CRAAP, RFI, RFP e RFQ, MePA, costo totale di possesso, licenze, SLA con RPO e RTO, GDPR e lock-in, matrice pesata con analisi di sensibilità e costo di un'API di AI.", "test_date": "2027-05-14", "practice_url": "contenuti/verifiche/5g-u6-simulazione.pdf", "test_url": null, "solutions_url": null}]);
